import {readFileSync} from 'node:fs';
import {CREDIT_LAB_CASE_VERSION,CREDIT_LAB_PACK_VERSION} from '../../../lib/credit-engine/contracts/credit-lab.ts';
import {INVARIANTS} from '../../../lib/credit-engine/credit-lab/validator.ts';
import {directFacts,sourceMaterial,finances,snapshot,bki,row,portfolio,reconciliationFinding,date} from './builders.mjs';
const required=(code,severity,scope='CREDIT_RISK')=>({code,level:'HARD',scope,severity,decisionImpact:scope==='GLOBAL_STOP'?'BLOCKING':scope==='INFORMATION'?'NON_BLOCKING':'REVIEW'});
const ruleStatus=(ruleCode,expected,subjectKey)=>({ruleCode,level:'HARD',expected,...(subjectKey?{subjectKey}:{})});
const caseDef=(caseId,title,material,expectation={})=>({caseDefinition:{schemaVersion:CREDIT_LAB_CASE_VERSION,caseId,revision:1,title,description:`Synthetic methodology scenario: ${title}. Expectations authored from approved Block 7 specification, independently of runner output.`,origin:'SYNTHETIC',status:'GOLDEN',reviewLevel:'INTERNAL_METHOD_REVIEW',partition:'GOLDEN_REGRESSION',subjectGroupId:`synthetic-group:${caseId}`,country:'RU',asOfDate:date,tags:['RU','synthetic','methodology'],materialKind:material.kind,expectation:{requiredFindings:[],forbiddenFindingCodes:[],ruleStatuses:[],facts:[],summary:{},invariantCodes:[...INVARIANTS],notes:['Internal methodology review only; not external or outcome validation.'],...expectation},review:{authoredByRole:'PRESCORE_METHOD_OWNER',reviewedByRole:'PRESCORE_METHOD_OWNER',approvedAt:'2026-09-09',rationale:'Initial scenarios and expected methodological behavior explicitly prescribed in Block 8 specification; internal implementation review.',labelBasis:['METHODOLOGY','FACTUAL_INVARIANT']},changeReason:null,warnings:[]},material});
export function buildGoldenEntries(){
 const entries=[],add=(n,title,material,e)=>entries.push(caseDef(`CL-RU-${String(n).padStart(3,'0')}`,title,material,e));
 const direct=(o={})=>({kind:'RISK_FACTS',facts:directFacts(o)});
 const src=mutate=>{const m=sourceMaterial();mutate?.(m);return m;};
 const stops=['RISK-LEGAL-ENTITY-TERMINATED','RISK-LEGAL-LIQUIDATION-ACTIVE','RISK-LEGAL-BANKRUPTCY-ACTIVE'];
 add(1,'Healthy full-data baseline',src(),{unexpectedFindings:'HARD',summary:{globalStopStatus:'NOT_TRIGGERED_WITH_AVAILABLE_DATA',dataReviewRequired:false}});
 add(2,'Legal data missing',direct({LEGAL_LIFECYCLE:null}),{forbiddenFindingCodes:stops,summary:{globalStopStatus:'INSUFFICIENT_DATA',dataReviewRequired:false}});
 add(3,'Explicit terminated entity',direct({LEGAL_LIFECYCLE:'TERMINATED'}),{requiredFindings:[required(stops[0],'CRITICAL','GLOBAL_STOP')]});
 add(4,'Active liquidation',direct({LEGAL_LIFECYCLE:'LIQUIDATION'}),{requiredFindings:[required(stops[1],'CRITICAL','GLOBAL_STOP')]});
 add(5,'Bankruptcy messages only',src(m=>{m.companyProfile.legal.bankruptcyMessages=3;}),{requiredFindings:[required('RISK-DATA-BANKRUPTCY-MESSAGES','MEDIUM','DATA_REVIEW')],forbiddenFindingCodes:[stops[2]]});
 add(6,'Explicit active bankruptcy',direct({LEGAL_LIFECYCLE:'BANKRUPTCY_ACTIVE'}),{requiredFindings:[required(stops[2],'CRITICAL','GLOBAL_STOP')]});
 add(7,'Negative equity',direct({FIN_EQUITY:-1000000}),{requiredFindings:[required('RISK-FIN-EQUITY-NON-POSITIVE','CRITICAL')],forbiddenFindingCodes:stops});
 add(8,'Two consecutive annual losses',src(m=>{m.analysis.financialAnalysisV2=finances([snapshot(2024,{2400:-500000}),snapshot(2025,{2400:-800000})]);}),{requiredFindings:[required('RISK-FIN-NET-LOSS-REPEATED','CRITICAL')],forbiddenFindingCodes:['RISK-FIN-NET-LOSS-CURRENT'],ruleStatuses:[ruleStatus('RISK-FIN-NET-LOSS-CURRENT','TRIGGERED')]});
 add(9,'Low liquidity and negative working capital',direct({FIN_CURRENT_RATIO:.6,FIN_WORKING_CAPITAL:-3000000}),{requiredFindings:[required('RISK-FIN-CURRENT-LIQUIDITY','HIGH'),required('RISK-FIN-WORKING-CAPITAL','HIGH')]});
 add(10,'Comparable annual revenue decline',direct({FIN_ANNUAL_REVENUE_CHANGE:-30}),{requiredFindings:[required('RISK-FIN-REVENUE-DECLINE','HIGH')]});
 add(11,'Low interest coverage',direct({FIN_INTEREST_COVERAGE:.7}),{requiredFindings:[required('RISK-FIN-INTEREST-COVERAGE','HIGH')]});
 add(12,'High bank debt-service burden',src(m=>{m.analysis.metricsV2.debtService.debtServiceToOperatingReceipts.value=.5;}),{requiredFindings:[required('RISK-CF-DEBT-SERVICE-BURDEN','HIGH')]});
 add(13,'Direct buyer concentration with adequate identity',src(m=>{m.analysis.metricsV2.customers.directCustomerTop1.value=.6;}),{requiredFindings:[required('RISK-CF-CUSTOMER-CONCENTRATION','HIGH')]});
 add(14,'Marketplace flow is not ultimate-customer concentration',src(m=>{m.analysis.metricsV2.customers.directCustomerTop1.value=.9;m.analysis.metricsV2.customers.intermediatedOperatingShare.value=.9;}),{forbiddenFindingCodes:['RISK-CF-CUSTOMER-CONCENTRATION'],ruleStatuses:[ruleStatus('RISK-CF-CUSTOMER-CONCENTRATION','INSUFFICIENT_DATA')]});
 add(15,'Unknown inflow is data review',direct({BANK_UNKNOWN_INFLOW_SHARE:.3}),{requiredFindings:[required('RISK-DATA-UNKNOWN-INFLOW-SHARE','HIGH','DATA_REVIEW')],forbiddenFindingCodes:stops});
 add(16,'Negative reconstructed balance is data review',direct({BANK_NEGATIVE_RECONSTRUCTED_DAYS:4}),{requiredFindings:[required('RISK-DATA-BALANCE-RECONSTRUCTION','HIGH','DATA_REVIEW')],forbiddenFindingCodes:[...stops,'RISK-CF-LIQUIDITY-STRESS']});
 add(17,'Fresh company BKI overdue with sixty-day history',src(m=>{m.analysis.creditHistory=bki({obligations:[row({overdueAmount:1000,maxDelinquencyDays:60})]});}),{requiredFindings:[required('RISK-BKI-CURRENT-OVERDUE','CRITICAL')],forbiddenFindingCodes:['RISK-BKI-HISTORICAL-DELINQUENCY']});
 add(18,'Old BKI preserves historical delinquency only',src(m=>{m.analysis.creditHistory=bki({reportDate:'2024-01-01',obligations:[row({overdueAmount:1000,maxDelinquencyDays:60})]});}),{requiredFindings:[required('RISK-BKI-HISTORICAL-DELINQUENCY','HIGH'),required('RISK-DATA-SOURCE-STALE','MEDIUM','DATA_REVIEW')],forbiddenFindingCodes:['RISK-BKI-CURRENT-OVERDUE'],facts:[{semanticCode:'BKI_OVERDUE',level:'HARD',status:'UNKNOWN',exactValue:null},{semanticCode:'BKI_HISTORY_DAYS',level:'HARD',exactValue:60,confidence:'MEDIUM'}]});
 add(19,'Personal owner BKI excluded',src(m=>{m.analysis.creditHistory=bki({subjectInn:'9900000002',relationshipToCompany:'Собственник',affectsCompanyDebt:false,obligations:[row({overdueAmount:100000,maxDelinquencyDays:90})]});}),{forbiddenFindingCodes:['RISK-BKI-CURRENT-OVERDUE','RISK-BKI-HISTORICAL-DELINQUENCY'],facts:[{semanticCode:'BKI_SCOPE_EXCLUDED',level:'HARD',exactValue:true}]});
 add(20,'Unresolved portfolio obligation',src(m=>{m.analysis.creditPortfolioV1.obligationMatches.push({observationGroupId:'synthetic-unknown',obligationId:null,outcome:'AMBIGUOUS',confidence:'LOW',reasonCodes:['OBLIGATION_MATCH_AMBIGUOUS'],candidateObligationIds:[],evidence:[]});}),{requiredFindings:[required('RISK-DATA-PORTFOLIO-OBLIGATION-UNRESOLVED','HIGH','DATA_REVIEW')]});
 add(21,'Company guarantorship is contingent',src(m=>{m.analysis.creditPortfolioV1=portfolio([row({role:'Поручитель',guaranteeAmount:1000000})]);}),{forbiddenFindingCodes:['RISK-BKI-CURRENT-OVERDUE','RISK-DATA-PORTFOLIO-OUTSTANDING-UNKNOWN'],facts:[{semanticCode:'PORTFOLIO_CONTINGENT_AMOUNT',level:'HARD',exactValue:1000000}]});
 add(22,'BFO versus quarterly same-fact conflict',src(m=>{m.analysis.reconciliationV1.findings=[reconciliationFinding()];}),{requiredFindings:[required('RISK-DATA-FINANCIAL-SAME-FACT-CONFLICT','HIGH','DATA_REVIEW')],forbiddenFindingCodes:stops});
 add(23,'Cash receipts versus accounting revenue relationship',src(m=>{m.analysis.reconciliationV1.findings=[reconciliationFinding('CASH_VS_ACCRUAL','RELATIONSHIP_OBSERVED')];}),{unexpectedFindings:'HARD',summary:{dataReviewRequired:false}});
 add(24,'Missing bank months',src(m=>{m.analysis.metricsV2.period.fullMonths=5;m.analysis.metricsV2.period.missingMonths=1;m.analysis.metricsV2.debtService.debtServiceToOperatingReceipts.value=.7;}),{requiredFindings:[required('RISK-DATA-BANK-COVERAGE','HIGH','DATA_REVIEW')],forbiddenFindingCodes:['RISK-CF-DEBT-SERVICE-BURDEN'],ruleStatuses:[ruleStatus('RISK-CF-DEBT-SERVICE-BURDEN','INSUFFICIENT_DATA')]});
 add(25,'Active enforcement above five percent of annual revenue',direct({LEGAL_ACTIVE_ENFORCEMENT_AMOUNT:600000,LEGAL_ENFORCEMENT_REVENUE_RATIO:.06}),{requiredFindings:[required('RISK-LEGAL-ACTIVE-ENFORCEMENT','HIGH')],forbiddenFindingCodes:stops});
 add(26,'Defendant claim is not confirmed debt',src(m=>{m.companyProfile.legalCaseItems=[{number:'synthetic-case',date:'2026-06-01',role:'DEFENDANT',amount:1000000}];}),{requiredFindings:[required('RISK-LEGAL-LITIGATION','INFO','INFORMATION')],forbiddenFindingCodes:stops});
 add(27,'New obligation detection requires data review',src(m=>{m.analysis.creditPortfolioV1.events.push({eventId:'synthetic-new',obligationId:null,type:'NEW_OBLIGATION_DETECTED',eventDate:date,effectiveDate:null,descriptionCode:'NEW_OBLIGATION_DETECTED',sourceIds:['synthetic:BKI'],evidence:[],confidence:'HIGH',warnings:[]});}),{requiredFindings:[required('RISK-DATA-NEW-OBLIGATION-DETECTED','MEDIUM','DATA_REVIEW')]});
 add(28,'Unmatched debt payment is not a hidden-loan conclusion',src(m=>{const p=m.analysis.creditPortfolioV1;p.paymentObservations.push({observationId:'synthetic-payment',companyInn:p.companyInn,transactionId:'synthetic-transaction',sourceIds:['synthetic:BANK_STATEMENT'],date,amount:1000,paymentKind:'INTEREST',principalAmount:null,interestAmount:1000,creditorName:'Синтетический кредитор',creditorInn:null,purpose:'Синтетический платёж процентов',contractReferences:[],classificationCode:'INTEREST_PAYMENT',classificationConfidence:'HIGH',evidence:[],warnings:[]});p.unmatchedPaymentObservationIds.push('synthetic-payment');}),{requiredFindings:[required('RISK-DATA-DEBT-PAYMENT-UNMATCHED','MEDIUM','DATA_REVIEW')]});
 add(29,'Low-confidence reconciliation is not promoted',src(m=>{m.analysis.reconciliationV1.findings=[reconciliationFinding('IDENTITY','CONFLICT','LOW')];}),{forbiddenFindingCodes:['RISK-DATA-COMPANY-IDENTITY-CONFLICT'],ruleStatuses:[ruleStatus('RISK-DATA-COMPANY-IDENTITY-CONFLICT','INSUFFICIENT_DATA')],facts:[{semanticCode:'RECON_IDENTITY_CONFLICTS',level:'HARD',confidence:'LOW',exactValue:1}]});
 add(30,'Multiple risks with cross-source separation',src(m=>{m.analysis.financialAnalysisV2=finances([snapshot(2025,{1300:-1000000,1500:9000000})]);m.analysis.metricsV2.debtService.debtServiceToOperatingReceipts.value=.5;m.analysis.creditHistory=bki({obligations:[row({overdueAmount:1000,maxDelinquencyDays:60})]});m.analysis.reconciliationV1.findings=[reconciliationFinding()];}),{requiredFindings:[required('RISK-FIN-EQUITY-NON-POSITIVE','CRITICAL'),required('RISK-CF-DEBT-SERVICE-BURDEN','HIGH'),required('RISK-BKI-CURRENT-OVERDUE','CRITICAL'),required('RISK-DATA-FINANCIAL-SAME-FACT-CONFLICT','HIGH','DATA_REVIEW')],forbiddenFindingCodes:stops});
 entries.push(caseDef('CL-RU-DEFECT-001','Current overdue with confirmed zero historical days',direct({BKI_OVERDUE:1000,BKI_HISTORY_DAYS:0}),{requiredFindings:[{...required('RISK-BKI-CURRENT-OVERDUE','MEDIUM'),reasonCodes:['CURRENT_OVERDUE'],forbiddenReasonCodes:['DELINQUENCY_1_29','DELINQUENCY_30_59','DELINQUENCY_60_PLUS']}],ruleStatuses:[ruleStatus('RISK-BKI-HISTORICAL-DELINQUENCY','NOT_TRIGGERED','synthetic-loan')],facts:[{semanticCode:'BKI_HISTORY_DAYS',level:'HARD',status:'KNOWN',exactValue:0}]}));
 return entries;
}
export function loadGoldenPack(){return {version:CREDIT_LAB_PACK_VERSION,revision:1,entries:buildGoldenEntries(),fingerprints:JSON.parse(readFileSync(new URL('./fingerprints-v0.json',import.meta.url),'utf8'))};}
